export function csvEscape(value: unknown) {
  let text = String(value ?? '')
  if (typeof value === 'string' && /^[\s]*[=+@-]/.test(text)) text = "'" + text
  return '"' + text.replaceAll('"', '""') + '"'
}
export function downloadCSV(filename: string, headers: string[], rows: unknown[][]) {
  const csv = '\uFEFF' + [headers, ...rows].map((row) => row.map(csvEscape).join(',')).join('\r\n')
  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8;' }))
  const a = document.createElement('a')
  a.href = url
  a.download = filename
  a.click()
  setTimeout(() => URL.revokeObjectURL(url), 1000)
}

export interface TableView {
  visibility: Record<string, boolean>
  order: string[]
  pinning: { left: string[]; right: string[] }
  sizing: Record<string, number>
}
export function readTableView(key?: string): Partial<TableView> {
  if (!key || typeof localStorage === 'undefined') return {}
  try {
    const value = JSON.parse(localStorage.getItem(key) ?? '{}')
    const strings = (v: unknown): v is string[] =>
      Array.isArray(v) && v.every((i) => typeof i === 'string')
    const result: Partial<TableView> = {}
    if (
      value.visibility &&
      typeof value.visibility === 'object' &&
      Object.values(value.visibility).every((v) => typeof v === 'boolean')
    )
      result.visibility = value.visibility
    if (strings(value.order)) result.order = value.order
    if (value.pinning && strings(value.pinning.left) && strings(value.pinning.right))
      result.pinning = value.pinning
    if (
      value.sizing &&
      typeof value.sizing === 'object' &&
      Object.values(value.sizing).every((v) => typeof v === 'number' && Number.isFinite(v) && v > 0)
    )
      result.sizing = value.sizing
    return result
  } catch {
    return {}
  }
}

export interface CellSpan {
  rowSpan: number
  colSpan: number
}
export function planCellSpans<T>(
  rows: T[],
  columns: string[],
  getSpan: (row: T, column: string, index: number) => Partial<CellSpan> | undefined,
) {
  const plan = new Map<string, CellSpan | null>(),
    covered = new Set<string>()
  rows.forEach((row, r) =>
    columns.forEach((column, c) => {
      const key = `${r}:${c}`
      if (covered.has(key)) {
        plan.set(key, null)
        return
      }
      const requested = getSpan(row, column, r),
        rowSpan = Math.min(rows.length - r, Math.max(0, requested?.rowSpan ?? 1)),
        colSpan = Math.min(columns.length - c, Math.max(0, requested?.colSpan ?? 1))
      if (!rowSpan || !colSpan) {
        plan.set(key, null)
        return
      }
      plan.set(key, { rowSpan, colSpan })
      for (let rr = r; rr < r + rowSpan; rr++)
        for (let cc = c; cc < c + colSpan; cc++)
          if (rr !== r || cc !== c) covered.add(`${rr}:${cc}`)
    }),
  )
  return plan
}
